'use client'

import { addCollection, Icon as IconifyIcon, type IconProps } from '@iconify/react/offline'
import lucide from '@/assets/icons/lucide.json'

// Offline build: icons come only from the local bundle (generated by `npm run icons`), never from api.iconify.design.
addCollection(lucide)

const Icon = ({ icon, ...props }: { icon: string } & Omit<IconProps, 'icon'>) => {
  return <IconifyIcon icon={`lucide:${icon}`} {...props} />
}
export default Icon
